window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3b58c3dd181fd2ae"]={"versions": [{"id": "FIG-3b58c3dd181fd2ae", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Teilprüfungsschritts „Read DataIDNibble“ innerhalb der Prüffunktion <code>E2E_P11Check()</code> des AUTOSAR E2E-Profils 11 (End-to-End-Kommunikationsabsicherung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten (Initial Node) und Endknoten (Activity Final Node)</li>\n<li>Verzweigungsknoten (Decision Node) und Zusammenführungsknoten (Merge Node)</li>\n<li>Bedingung/Guard: <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code> mit den Ausgängen <code>[TRUE]</code> und <code>[FALSE]</code></li>\n<li>Aktionsknoten: <code>Copy DataIDNibble from bit-position Config-&gt;NibbleOffset in Data in Little Endian order to uint8 local variable ReceivedNibble</code></li>\n<li>Notizkommentar (Comment/Note) assoziiert mit der Aktion:</li>\n<li><code>Byte position in data array can be obtained by:</code></li>\n</ul>\n<p class=\"fig-p\"><code>Byte = Data[Config-&gt;NibbleOffset &gt;&gt; 3]</code></p>\n<ul class=\"fig-list\">\n<li><code>Nibble within byte can be obtained by:</code></li>\n</ul>\n<p class=\"fig-p\"><code>Counter = (Byte &lt;&lt; (Config-&gt;NibbleOffset &amp; 0x7)) &amp; 0xF</code></p>\n<ul class=\"fig-list\">\n<li>Konfigurationsstruktur <code>Config</code> mit Parametern <code>DataIDMode</code> und <code>NibbleOffset</code>, Datenarray <code>Data</code> sowie lokale Variable <code>ReceivedNibble</code> (Typ <code>uint8</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Startknoten in den ersten Entscheidungsknoten.</li>\n<li>Evaluierung des Modus <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Falls <code>[TRUE]</code>: Übergang zur Aktion „Copy DataIDNibble from bit-position Config->NibbleOffset in Data in Little Endian order to uint8 local variable ReceivedNibble“. Die Extraktion des relevanten Nibbles aus dem Datenarray erfolgt anhand der Bitposition <code>Config-&gt;NibbleOffset</code>. Anschließend Übergang zum Zusammenführungsknoten.</li>\n<li>Falls <code>[FALSE]</code>: Umgehung der Extraktionsaktion über die <code>[FALSE]</code>-Kante direkt zum Zusammenführungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Austritt aus dem Zusammenführungsknoten in den Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Aktivität spezifiziert das funktionale Verhalten der Anforderung [PRS_E2E_00582].</li>\n<li>Ist <code>DataIDMode</code> nicht auf <code>E2E_P11_DATAID_NIBBLE</code> konfiguriert, wird kein Nibble aus den Nutzdaten ausgelesen.</li>\n<li>Die beigefügte Notiz enthält eine beispielhafte Implementierungshilfe zur Bit- und Byte-Adressierung; die Formel <code>(Byte &lt;&lt; (Config-&gt;NibbleOffset &amp; 0x7)) &amp; 0xF</code> führt jedoch zu einem fehlerhaften Linksshift bei der Nibble-Isolierung.</li>\n</ul>"}, {"id": "FIG-2ec08e6ce53890bd", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Teilprüfungsschritts „Read DataIDNibble“ innerhalb der Prüffunktion <code>E2E_P11Check()</code> des AUTOSAR E2E-Profils 11 (End-to-End-Kommunikationsabsicherung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten (Initial Node) und Endknoten (Activity Final Node)</li>\n<li>Verzweigungsknoten (Decision Node) und Zusammenführungsknoten (Merge Node)</li>\n<li>Bedingung/Guard: <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code> (zweizeilig dargestellt) mit den Ausgängen <code>[TRUE]</code> und <code>[FALSE]</code></li>\n<li>Aktionsknoten: <code>Copy DataIDNibble from bit-position Config-&gt;NibbleOffset in Data in Little Endian order to uint8 local variable ReceivedNibble</code></li>\n<li>Notizkommentar (Comment/Note) assoziiert mit der Aktion:</li>\n<li><code>Byte position in data array can be obtained by:</code></li>\n</ul>\n<p class=\"fig-p\"><code>Byte = Data[Config-&gt;NibbleOffset &gt;&gt; 3]</code></p>\n<ul class=\"fig-list\">\n<li><code>Nibble within byte can be obtained by:</code></li>\n</ul>\n<p class=\"fig-p\"><code>Counter = (Byte &gt;&gt; (Config-&gt;NibbleOffset &amp; 0x7)) &amp; 0xF</code></p>\n<ul class=\"fig-list\">\n<li>Konfigurationsstruktur <code>Config</code> mit Parametern <code>DataIDMode</code> und <code>NibbleOffset</code>, Datenarray <code>Data</code> sowie lokale Variable <code>ReceivedNibble</code> (Typ <code>uint8</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Startknoten in den ersten Entscheidungsknoten.</li>\n<li>Evaluierung des Modus <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Falls <code>[TRUE]</code>: Übergang zur Aktion „Copy DataIDNibble from bit-position Config->NibbleOffset in Data in Little Endian order to uint8 local variable ReceivedNibble“. Die Extraktion des relevanten Nibbles aus dem Datenarray erfolgt anhand der Bitposition <code>Config-&gt;NibbleOffset</code>. Anschließend Übergang zum Zusammenführungsknoten.</li>\n<li>Falls <code>[FALSE]</code>: Umgehung der Extraktionsaktion über die <code>[FALSE]</code>-Kante direkt zum Zusammenführungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Austritt aus dem Zusammenführungsknoten in den Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Aktivität spezifiziert das funktionale Verhalten der Anforderung [PRS_E2E_00582].</li>\n<li>Ist <code>DataIDMode</code> nicht auf <code>E2E_P11_DATAID_NIBBLE</code> konfiguriert, wird kein Nibble aus den Nutzdaten ausgelesen.</li>\n<li>Die beigefügte Notiz enthält eine Implementierungsvorschrift zur Bit- und Byte-Adressierung, bei der das Nibble durch einen Rechtsshift um den Bit-Offset innerhalb des Bytes isoliert und mit <code>0xF</code> maskiert wird: <code>Counter = (Byte &gt;&gt; (Config-&gt;NibbleOffset &amp; 0x7)) &amp; 0xF</code>.</li>\n</ul>"}, {"id": "FIG-84629196ed98b947", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Teilprüfungsschritts „Read DataIDNibble“ innerhalb der Prüffunktion <code>E2E_P11Check()</code> des AUTOSAR E2E-Profils 11 (End-to-End-Kommunikationsabsicherung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten (Initial Node) und Endknoten (Activity Final Node)</li>\n<li>Verzweigungsknoten (Decision Node) und Zusammenführungsknoten (Merge Node)</li>\n<li>Bedingung/Guard: <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code> (zweizeilig dargestellt) mit den Ausgängen <code>[TRUE]</code> und <code>[FALSE]</code></li>\n<li>Aktionsknoten: <code>Copy DataIDNibble from bit-position Config-&gt;NibbleOffset in Data in Little Endian order to uint8 local variable ReceivedNibble</code></li>\n<li>Notizkommentar (Comment/Note) assoziiert mit der Aktion:</li>\n<li><code>Byte position in data array can be obtained by:</code></li>\n</ul>\n<p class=\"fig-p\"><code>Byte = Data[Config-&gt;NibbleOffset &gt;&gt; 3]</code></p>\n<ul class=\"fig-list\">\n<li><code>Nibble within byte can be obtained by:</code></li>\n</ul>\n<p class=\"fig-p\"><code>Counter = (Byte &gt;&gt; (Config-&gt;NibbleOffset &amp; 0x7)) &amp; 0xF</code></p>\n<ul class=\"fig-list\">\n<li>Konfigurationsstruktur <code>Config</code> mit Parametern <code>DataIDMode</code> und <code>NibbleOffset</code>, Datenarray <code>Data</code> sowie lokale Variable <code>ReceivedNibble</code> (Typ <code>uint8</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Startknoten in den ersten Entscheidungsknoten.</li>\n<li>Evaluierung des Modus <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Falls <code>[TRUE]</code>: Übergang zur Aktion „Copy DataIDNibble from bit-position Config->NibbleOffset in Data in Little Endian order to uint8 local variable ReceivedNibble“. Die Extraktion des relevanten Nibbles aus dem Datenarray erfolgt anhand der Bitposition <code>Config-&gt;NibbleOffset</code>. Anschließend Übergang zum Zusammenführungsknoten.</li>\n<li>Falls <code>[FALSE]</code>: Umgehung der Extraktionsaktion über die <code>[FALSE]</code>-Kante direkt zum Zusammenführungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Austritt aus dem Zusammenführungsknoten in den Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Aktivität spezifiziert das funktionale Verhalten der Anforderung [PRS_E2E_00582].</li>\n<li>Ist <code>DataIDMode</code> nicht auf <code>E2E_P11_DATAID_NIBBLE</code> konfiguriert, wird kein Nibble aus den Nutzdaten ausgelesen.</li>\n<li>Die beigefügte Notiz enthält eine Implementierungsvorschrift zur Bit- und Byte-Adressierung, bei der das Nibble durch einen Rechtsshift um den Bit-Offset innerhalb des Bytes isoliert und mit <code>0xF</code> maskiert wird: <code>Counter = (Byte &gt;&gt; (Config-&gt;NibbleOffset &amp; 0x7)) &amp; 0xF</code>.</li>\n</ul>"}, {"id": "FIG-16439d30c977277e", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Teilprüfungsschritts „Read DataIDNibble“ innerhalb der Prüffunktion <code>E2E_P11Check()</code> des AUTOSAR E2E-Profils 11 (End-to-End-Kommunikationsabsicherung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten (Initial Node) und Endknoten (Activity Final Node)</li>\n<li>Verzweigungsknoten (Decision Node) und Zusammenführungsknoten (Merge Node)</li>\n<li>Bedingung/Guard: <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code> (zweizeilig dargestellt) mit den Ausgängen <code>[TRUE]</code> und <code>[FALSE]</code></li>\n<li>Aktionsknoten: <code>Copy DataIDNibble from bit-position Config-&gt;NibbleOffset in Data in Little Endian order to uint8 local variable ReceivedNibble</code></li>\n<li>Notizkommentar (Comment/Note) assoziiert mit der Aktion:</li>\n<li><code>Byte position in data array can be obtained by:</code></li>\n</ul>\n<p class=\"fig-p\"><code>Byte = Data[Config-&gt;NibbleOffset &gt;&gt; 3]</code></p>\n<ul class=\"fig-list\">\n<li><code>Nibble within byte can be obtained by:</code></li>\n</ul>\n<p class=\"fig-p\"><code>Counter = (Byte &gt;&gt; (Config-&gt;NibbleOffset &amp; 0x7)) &amp; 0xF</code></p>\n<ul class=\"fig-list\">\n<li>Konfigurationsstruktur <code>Config</code> mit Parametern <code>DataIDMode</code> und <code>NibbleOffset</code>, Datenarray <code>Data</code> sowie lokale Variable <code>ReceivedNibble</code> (Typ <code>uint8</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Startknoten in den ersten Entscheidungsknoten.</li>\n<li>Evaluierung des Modus <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Falls <code>[TRUE]</code>: Übergang zur Aktion „Copy DataIDNibble from bit-position Config->NibbleOffset in Data in Little Endian order to uint8 local variable ReceivedNibble“. Die Extraktion des relevanten Nibbles aus dem Datenarray erfolgt anhand der Bitposition <code>Config-&gt;NibbleOffset</code>. Anschließend Übergang zum Zusammenführungsknoten.</li>\n<li>Falls <code>[FALSE]</code>: Umgehung der Extraktionsaktion über die <code>[FALSE]</code>-Kante direkt zum Zusammenführungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Austritt aus dem Zusammenführungsknoten in den Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Aktivität spezifiziert das funktionale Verhalten der Anforderung [PRS_E2E_00582].</li>\n<li>Ist <code>DataIDMode</code> nicht auf <code>E2E_P11_DATAID_NIBBLE</code> konfiguriert, wird kein Nibble aus den Nutzdaten ausgelesen.</li>\n<li>Die beigefügte Notiz enthält eine Implementierungsvorschrift zur Bit- und Byte-Adressierung, bei der das Nibble durch einen Rechtsshift um den Bit-Offset innerhalb des Bytes isoliert und mit <code>0xF</code> maskiert wird: <code>Counter = (Byte &gt;&gt; (Config-&gt;NibbleOffset &amp; 0x7)) &amp; 0xF</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-3b58c3dd181fd2ae", "to": "FIG-2ec08e6ce53890bd", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Die Berechnungsformel im Notizkommentar zur Extraktion des Nibbles innerhalb eines Bytes (<code>Nibble within byte can be obtained by:</code>) wurde von <code>Counter = (Byte &lt;&lt; (Config-&gt;NibbleOffset &amp; 0x7)) &amp; 0xF</code> zu <code>Counter = (Byte &gt;&gt; (Config-&gt;NibbleOffset &amp; 0x7)) &amp; 0xF</code> korrigiert (Rechtsshift <code>&gt;&gt;</code> statt Linksshift <code>&lt;&lt;</code>).</li>\n<li>Die Beschriftung des Verzweigungszweigs <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code> wurde umbrochen (zweizeilig dargestellt).</li>\n</ul>"}, {"from": "FIG-2ec08e6ce53890bd", "to": "FIG-84629196ed98b947", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Die Abbildung wurde neu gerendert und skaliert (Bildabmessungen von 828x362 auf 788x345 Pixel).</li>\n<li>Der Zeilenabstand und die vertikale Textplatzierung in der Notizbox sowie an den Guards/Labels wurden minimal angepasst.</li>\n</ul>"}, {"from": "FIG-84629196ed98b947", "to": "FIG-16439d30c977277e", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
